/*
 * PDF Private service worker: makes the site work offline.
 * Generated by _build/build.py; edit _build/sw.template.js instead.
 *
 * Pages: network first (so updates show up), cache as fallback when offline.
 * Everything else: cache first (versioned by content hash).
 * Only this site's own files are ever cached; user PDFs are never touched.
 */
const CACHE = 'pdfprivate-8ceda6731ecb';
const ASSETS = [
        "/",
        "/pages/merge.html",
        "/pages/compress.html",
        "/pages/split.html",
        "/pages/images-to-pdf.html",
        "/pages/pdf-to-images.html",
        "/pages/redact.html",
        "/pages/remove-metadata.html",
        "/pages/rotate.html",
        "/pages/delete-pages.html",
        "/pages/compress-pdf-to-100kb.html",
        "/pages/compress-pdf-to-200kb.html",
        "/pages/compress-pdf-to-500kb.html",
        "/pages/compress-pdf-to-1mb.html",
        "/pages/compress-pdf-to-2mb.html",
        "/privacy.html",
        "/terms.html",
        "/css/styles.css",
        "/css/tailwind.css",
        "/js/app.js",
        "/js/compress.js",
        "/js/delete-pages.js",
        "/js/images-to-pdf.js",
        "/js/merge.js",
        "/js/pdf-to-images.js",
        "/js/redact.js",
        "/js/remove-metadata.js",
        "/js/rotate.js",
        "/js/split.js",
        "/js/sw-register.js",
        "/vendor/jszip.min.js",
        "/vendor/pdf-lib.min.js",
        "/vendor/pdf.min.js",
        "/vendor/pdf.worker.min.js",
        "/fonts/space-grotesk-latin-500-normal.woff2",
        "/fonts/space-grotesk-latin-700-normal.woff2",
        "/icons/icon-192.png",
        "/icons/icon-512.png",
        "/icons/icon-maskable-512.png",
        "/icons/icon.svg",
        "/icons/og-image.png",
        "/manifest.webmanifest"
    ];

self.addEventListener('install', (event) => {
    event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
    event.waitUntil(
        caches.keys()
            .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
            .then(() => self.clients.claim())
    );
});

self.addEventListener('fetch', (event) => {
    const request = event.request;
    const url = new URL(request.url);
    if (request.method !== 'GET' || url.origin !== self.location.origin) return;

    if (request.mode === 'navigate') {
        event.respondWith(
            fetch(request)
                .then((response) => {
                    const copy = response.clone();
                    caches.open(CACHE).then((cache) => cache.put(request, copy));
                    return response;
                })
                .catch(() => caches.match(request, { ignoreSearch: true }).then((r) => r || caches.match('/')))
        );
        return;
    }

    event.respondWith(caches.match(request).then((cached) => cached || fetch(request)));
});
